/**
 * @file    app.h
 * @brief   The top level of our firmware: what the board does.
 *
 * main.c (generated by CubeMX) sets up the chip and then calls only these
 * two functions, from inside its USER CODE blocks:
 *
 *     app_init();          once, after all peripherals are initialised
 *     while (1) {
 *         app_poll();      over and over, forever
 *     }
 *
 * Everything we write hangs off these two calls, so CubeMX can regenerate
 * main.c without touching our code.
 */
#ifndef APP_H
#define APP_H

/**
 * @brief  One-time start-up: read the slave address, start the drivers.
 *
 * Call once, after the MX_..._Init() functions in main.c.
 */
void app_init(void);

/**
 * @brief  One round of work: handle a Modbus frame if one has arrived.
 *
 * Called from the main loop, so it runs thousands of times per second.
 * Rule: it must never wait for anything (no HAL_Delay(), no waiting for
 * a sensor). If it did, bytes arriving on RS-485 meanwhile could be missed.
 * Anything slow is split into small steps that each return at once.
 */
void app_poll(void);

#endif /* APP_H */
